  Theorem stack_not_afootQ : forall a, aceil <= a -> ~ afoot s a.
  Proof.
    intros a Ha AF. acb. destruct (afoot_aobjQ a AF) as [H|H].
    - apply aobj_rangeQ in H. unfold aband, AIMG_LO, AIMG_TOP, ALOWSH_LO in H. lia.
    - unfold AHI_LO in H. lia.
  Qed.

  Theorem image_not_afootQ : forall a, ARW_LO <= a < AIMG_TOP -> ~ astatic a -> ~ afoot s a.
  Proof.
    intros a Ha Hn AF. destruct (afoot_aobjQ a AF) as [H|H].
    - apply aobj_rangeQ in H. destruct H as [H|[_ H]]; [unfold aband, AHI_LO, AIMG_LO, AIMG_TOP, ARW_LO in *; lia| exact (Hn H)].
    - unfold ASHADOW_BASE, AIMG_TOP in *. lia.
  Qed.

  (* [comment removed for export] *)
  Theorem fakestack_not_afootQ : forall a, a_fsb s <= a < a_fsb s + AFS_SIZE -> ~ afoot s a.
  Proof.
    intros a Ha AF. pose proof PL as (S1 & S2 & S3 & P1 & P2 & P3 & T1 & T2 & T3 & X1 & X2 & X3 & D1 & D2 & D3 & D4 & D5 & F1 & F2 & D6 & D7 & D8 & D9 & SEC & SEC2 & TCX).
    destruct (afoot_aobjQ a AF) as [H|H].
    - unfold aobj in H.
      destruct H as [H|[H|[H|[H|[(h0 & Hsc & H)|[H _]]]]]].
      + clear - Ha H D6; try acb. unfold disj, a_sb in *. lia.
      + clear - Ha H D7; try acb. unfold disj in *. lia.
      + clear - Ha H D8; try acb. unfold disj in *. lia.
      + clear - Ha H D9; try acb. unfold disj in *. lia.
      + pose proof (SEC h0 Hsc) as (_ & _ & _ & _ & _ & _ & _ & _ & G). clear - Ha H G; try acb. unfold disj in *. lia.
      + clear - Ha H F1. aunf. lia.
    - clear - Ha H F1. aunf. unfold ASHADOW_BASE in *. lia.
  Qed.

